@Service
public class FeedFanoutService {
    @Autowired private FollowerRepository followerRepo;
    @Autowired private RedisTemplate<String, String> redis;

    public void fanoutPost(String authorId, String postId) {
        // BUG: Pure fanout-on-write attempts to insert into millions of user lists synchronously
        List<String> followerIds = followerRepo.findFollowerIds(authorId);
        for (String followerId : followerIds) {
            redis.opsForList().leftPush("feed:" + followerId, postId);
            redis.opsForList().trim("feed:" + followerId, 0, 800);
        }
    }
}

